mapper.select:
SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, R.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.CODE_ID ASC) AS RNUM, A.CODE_ID, A.CODE_ID_NM, A.CODE_ID_DC, A.USE_AT, TO_CHAR(A.LAST_UPDT_PNTTM, 'YYYY-MM-DD AM HH12:MI') AS LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID, A.CL_CODE, (SELECT COUNT(*) FROM COMTCCMMNDETAILCODE WHERE CODE_ID = A.CODE_ID) AS CHILD_CNT FROM COMTCCMMNCODE A WHERE 1=1
AND A.CL_CODE = #{params.clCode}
AND A.CODE_ID LIKE CONCAT('%', #{params.searchKeyword}, '%')
AND A.CODE_ID_NM LIKE CONCAT('%', #{params.searchKeyword}, '%')
) R ORDER BY RNUM ASC LIMIT #{params.recordCountPerPage} OFFSET #{params.firstIndex}

mapper.insert:
INSERT INTO COMTCCMMNCODE
(
    CODE_ID, CODE_ID_NM, CODE_ID_DC, USE_AT, CL_CODE,
    FRST_REGIST_PNTTM, FRST_REGISTER_ID, LAST_UPDT_PNTTM, LAST_UPDUSR_ID
)
VALUES
    (
        #{codeId}, #{codeIdNm}, #{codeIdDc}, #{useAt}, #{clCode},
        NOW(), #{userId}, NOW(), #{userId}
    )
